text./plugins/native-fx/colorcurves.css:
.zoidium-color-curves-row {
  grid-template-columns: minmax(0, 1fr) !important;
  padding-bottom: 4px !important;
  white-space: normal !important;
}

.zoidium-color-curves-row > div:first-child {
  padding-bottom: 3px;
}

.zoidium-color-curves-row > div:nth-child(2) {
  min-width: 0;
  padding: 0 5px 5px !important;
}

.zoidium-color-curves-control,
.zoidium-color-curves-editor,
.zoidium-color-curves-control * {
  box-sizing: border-box;
  font-family: var(--zui-font);
}

.zoidium-color-curves-control {
  width: 100%;
  min-width: 0;
  color: var(--zui-text);
}

.zoidium-color-curves-editor {
  --zoidium-curve-channel: var(--zui-value);
  width: 100%;
  min-width: 0;
  border: 1px solid var(--zui-border);
  background: var(--zui-border-soft);
}

.zoidium-color-curves-editor[data-channel="red"] {
  --zoidium-curve-channel: #c46f6f;
}

.zoidium-color-curves-editor[data-channel="green"] {
  --zoidium-curve-channel: #6fa47a;
}

.zoidium-color-curves-editor[data-channel="blue"] {
  --zoidium-curve-channel: #718fc4;
}

.zoidium-color-curves-toolbar {
  display: grid;
  grid-template-columns: repeat(4, minmax(28px, 1fr)) auto;
  min-height: 29px;
  border-bottom: 1px solid var(--zui-border);
  background: var(--zui-bg);
}

.zoidium-color-curves-channel,
.zoidium-color-curves-reset {
  min-width: 0;
  height: 28px;
  padding: 0 7px;
  overflow: hidden;
  color: var(--zui-text-muted);
  background: transparent;
  border: 1px solid transparent;
  border-right-color: var(--zui-border);
  outline: 0;
  font-size: var(--zui-font-size-small);
  line-height: 26px;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.zoidium-color-curves-channel:hover,
.zoidium-color-curves-reset:hover {
  color: var(--zui-text-strong);
  background: var(--zui-hover);
}

.zoidium-color-curves-channel:focus-visible,
.zoidium-color-curves-reset:focus-visible {
  border-color: var(--zui-accent);
}

.zoidium-color-curves-channel.is-active {
  color: var(--zui-text-bright);
  background: var(--zui-bg-input);
  border-bottom-color: var(--zoidium-curve-channel);
}

.zoidium-color-curves-reset {
  display: flex;
  align-items: center;
  gap: 4px;
  justify-content: center;
  width: auto;
  padding: 0 6px;
  border-right-color: transparent;
}

.zoidium-color-curves-reset svg {
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
  fill: currentColor;
  pointer-events: none;
}

.zoidium-color-curves-reset span {
  overflow: hidden;
  text-overflow: ellipsis;
}

.zoidium-color-curves-graph {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  touch-action: none;
  cursor: crosshair;
  background-color: var(--zui-bg-input);
  outline: 0;
}

.zoidium-color-curves-graph:focus-visible {
  box-shadow: inset 0 0 0 1px var(--zui-accent);
}

.zoidium-color-curves-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.zoidium-color-curves-grid {
  fill: none;
  pointer-events: none;
  stroke: color-mix(in srgb, var(--zui-border-soft) 55%, var(--zui-hover));
  stroke-width: 1px;
  vector-effect: non-scaling-stroke;
}

.zoidium-color-curves-grid-center {
  stroke: var(--zui-hover);
}

.zoidium-color-curves-diagonal,
.zoidium-color-curves-reference,
.zoidium-color-curves-active {
  fill: none;
  pointer-events: none;
  vector-effect: non-scaling-stroke;
}

.zoidium-color-curves-diagonal {
  stroke: color-mix(in srgb, var(--zui-hover) 55%, var(--zui-text-faint));
  stroke-width: 1px;
  stroke-dasharray: 3 3;
}

.zoidium-color-curves-reference {
  stroke: var(--zui-text-faint);
  stroke-width: 1px;
  opacity: 0.65;
}

.zoidium-color-curves-active {
  stroke: var(--zoidium-curve-channel);
  stroke-width: 2px;
}

.zoidium-color-curves-point-hit {
  fill: transparent;
  cursor: grab;
}

.zoidium-color-curves-point {
  fill: var(--zui-bg-input);
  stroke: var(--zoidium-curve-channel);
  stroke-width: 2px;
  pointer-events: none;
  vector-effect: non-scaling-stroke;
}

.zoidium-color-curves-point-wrap.is-selected .zoidium-color-curves-point {
  fill: var(--zoidium-curve-channel);
  stroke: var(--zui-text-bright);
}

.zoidium-color-curves-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 24px;
  padding: 3px 6px;
  overflow: hidden;
  color: var(--zui-text-muted);
  background: var(--zui-border-soft);
  border-top: 1px solid var(--zui-border);
  font-size: var(--zui-font-size-compact);
  line-height: 17px;
}

.zoidium-color-curves-status,
.zoidium-color-curves-hint {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.zoidium-color-curves-status {
  color: var(--zoidium-curve-channel);
}

.zoidium-color-curves-hint {
  color: var(--zui-text-faint);
  text-align: right;
}

text./plugins/native-fx/effects/advspill.js:
"use strict";

// Algorithm adapted from EffectCraft (MIT OR Apache-2.0).
//
// Advanced Spill Suppressor: removes key-colour spill (typically green) from
// foreground edges. Standard suppresses the excess of the key colour's
// dominant channel over the larger of the other two. Ultra additionally limits
// suppression to hues near the key colour (Tolerance), narrows the spill
// limit (Spill Range), and can put the removed light back as neutral
// brightness (Spill Color Correction, Luma Correction) or grey the pixel
// (Desaturate).
//
// The reference analyses the whole frame to pick the dominant channel in
// Standard mode; this port uses the dominant channel of the Key Color
// instead, which matches for green/blue screens and keeps the effect a
// deterministic single pass with no frame analysis.

function aspPrimary(color) {
  var r = color[0];
  var g = color[1];
  var b = color[2];
  if (g >= r && g >= b) return [1, 0, 2];
  if (b >= r && b >= g) return [2, 0, 1];
  return [0, 1, 2];
}

function aspHue(color) {
  var r = color[0];
  var g = color[1];
  var b = color[2];
  var mx = Math.max(r, Math.max(g, b));
  var mn = Math.min(r, Math.min(g, b));
  var d = mx - mn;
  if (d < 0.0000001) return 0;
  var h;
  if (mx === r) {
    h = (g - b) / d;
    if (g < b) h += 6;
    h /= 6;
  } else if (mx === g) {
    h = ((b - r) / d + 2) / 6;
  } else {
    h = ((r - g) / d + 4) / 6;
  }
  return h;
}

ZoidiumPluginApis.defineFilter.call(this, {
  displayName: "Advanced Spill Suppressor",
  fragShaderUrl: "/plugins/native-fx/shaders/fx_advspill.glsl",
  uniforms: {
    uvScale: { type: "v2", value: new THREE.Vector2(1, 1) },
    keyPrimary: { type: "f", value: 1 },
    keyOther1: { type: "f", value: 0 },
    keyOther2: { type: "f", value: 2 },
    suppression: { type: "f", value: 1 },
    spillRange: { type: "f", value: 0 },
    lumaCorrection: { type: "f", value: 0 },
    tolerance: { type: "f", value: 1 },
    desaturate: { type: "f", value: 0 },
    neutral: { type: "f", value: 0 },
    keyHue: { type: "f", value: 1 / 3 },
  },
  properties: {
    enabled: {
      dynamic: true,
      name: "Enabled",
      type: PZ.property.type.OPTION,
      value: 1,
      items: "off;on",
    },
    method: {
      dynamic: true,
      name: "Method",
      type: PZ.property.type.OPTION,
      value: 0,
      items: "Standard;Ultra",
    },
    keyColor: {
      dynamic: true,
      name: "Key Color",
      type: PZ.property.type.COLOR,
      value: [0, 1, 0],
    },
    suppression: {
      dynamic: true,
      name: "Suppression",
      type: PZ.property.type.NUMBER,
      value: 100,
      min: 0,
      max: 200,
      step: 1,
      decimals: 0,
    },
    tolerance: {
      dynamic: true,
      name: "Tolerance",
      type: PZ.property.type.NUMBER,
      value: 50,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
    desaturate: {
      dynamic: true,
      name: "Desaturate",
      type: PZ.property.type.NUMBER,
      value: 0,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
    spillRange: {
      dynamic: true,
      name: "Spill Range",
      type: PZ.property.type.NUMBER,
      value: 50,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
    spillColorCorrection: {
      dynamic: true,
      name: "Spill Color Correction",
      type: PZ.property.type.NUMBER,
      value: 0,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
    lumaCorrection: {
      dynamic: true,
      name: "Luma Correction",
      type: PZ.property.type.NUMBER,
      value: 0,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
  },
  update(frame) {
    if (!this.pass) return;
    var uniforms = this.pass.uniforms;
    this.pass.enabled = this.properties.enabled.get(frame) === 1;
    var ultra = this.properties.method.get(frame) === 1;
    var key = this.properties.keyColor.get(frame);
    var order = aspPrimary(key);
    uniforms.keyPrimary.value = order[0];
    uniforms.keyOther1.value = order[1];
    uniforms.keyOther2.value = order[2];
    uniforms.keyHue.value = aspHue(key);
    uniforms.suppression.value = this.properties.suppression.get(frame) / 100;
    if (ultra) {
      uniforms.tolerance.value = this.properties.tolerance.get(frame) / 100;
      uniforms.desaturate.value = this.properties.desaturate.get(frame) / 100;
      uniforms.spillRange.value = this.properties.spillRange.get(frame) / 100;
      uniforms.neutral.value = this.properties.spillColorCorrection.get(frame) / 100;
      uniforms.lumaCorrection.value = this.properties.lumaCorrection.get(frame) / 100;
    } else {
      uniforms.tolerance.value = 1;
      uniforms.desaturate.value = 0;
      uniforms.spillRange.value = 0;
      uniforms.neutral.value = 0;
      uniforms.lumaCorrection.value = 0;
    }
  },
});

text./plugins/native-fx/effects/colorcurves.j:
"use strict";

(function (global, effect) {
  const CONTROL_ID = "native-fx/color-curves";
  const SHADER_URL = "/plugins/native-fx/shaders/fx_colorcurves.glsl";
  const STYLE_URL = "/plugins/native-fx/colorcurves.css";
  const STYLE_ID = "zoidium-color-curves-style";
  const LUT_SIZE = 256;
  // Quarter-step guides drawn inside the plot (256-unit viewBox).
  const GRID_PATH = "M64 0V256M192 0V256M0 64H256M0 192H256";
  const GRID_CENTER_PATH = "M128 0V256M0 128H256";
  const MAX_POINTS = 16;
  const CHANNELS = [
    { id: "composite", shortName: "RGB", name: "RGB" },
    { id: "red", shortName: "R", name: "Red" },
    { id: "green", shortName: "G", name: "Green" },
    { id: "blue", shortName: "B", name: "Blue" },
  ];

  function clamp(value, minimum, maximum) {
    return Math.min(maximum, Math.max(minimum, value));
  }

  function roundPoint(value) {
    return Math.round(clamp(Number(value) || 0, 0, 1) * 10000) / 10000;
  }

  function identityPoints() {
    return [[0, 0], [1, 1]];
  }

  function defaultState() {
    return {
      version: 1,
      composite: identityPoints(),
      red: identityPoints(),
      green: identityPoints(),
      blue: identityPoints(),
    };
  }

  function sanitizePoints(value) {
    const points = Array.isArray(value)
      ? value
          .map((point) => {
            if (Array.isArray(point)) return [roundPoint(point[0]), roundPoint(point[1])];
            if (point && typeof point === "object") {
              return [roundPoint(point.x), roundPoint(point.y)];
            }
            return null;
          })
          .filter(Boolean)
          .sort((first, second) => first[0] - second[0])
      : [];

    const unique = [];
    for (const point of points) {
      if (unique.length && Math.abs(unique[unique.length - 1][0] - point[0]) < 0.0001) {
        unique[unique.length - 1] = point;
      } else {
        unique.push(point);
      }
    }
    if (!unique.length || unique[0][0] > 0.0001) unique.unshift([0, 0]);
    else unique[0][0] = 0;
    if (unique[unique.length - 1][0] < 0.9999) unique.push([1, 1]);
    else unique[unique.length - 1][0] = 1;
    if (unique.length > MAX_POINTS) {
      const middle = unique.slice(1, -1).slice(0, MAX_POINTS - 2);
      return [unique[0], ...middle, unique[unique.length - 1]];
    }
    return unique;
  }

  function parseState(value) {
    let parsed = value;
    if (typeof value === "string") {
      try {
        parsed = JSON.parse(value);
      } catch (_error) {
        parsed = null;
      }
    }
    const fallback = defaultState();
    if (!parsed || typeof parsed !== "object") return fallback;
    return {
      version: 1,
      composite: sanitizePoints(parsed.composite),
      red: sanitizePoints(parsed.red),
      green: sanitizePoints(parsed.green),
      blue: sanitizePoints(parsed.blue),
    };
  }

  function serializeState(state) {
    const normalized = { version: 1 };
    for (const channel of CHANNELS) {
      normalized[channel.id] = sanitizePoints(state[channel.id]).map((point) => [
        roundPoint(point[0]),
        roundPoint(point[1]),
      ]);
    }
    return JSON.stringify(normalized);
  }

  function createSampler(value) {
    const points = sanitizePoints(value);
    const count = points.length;
    const widths = [];
    const slopes = [];
    const tangents = new Array(count).fill(0);
    for (let index = 0; index < count - 1; index += 1) {
      const width = Math.max(points[index + 1][0] - points[index][0], 0.0001);
      widths[index] = width;
      slopes[index] = (points[index + 1][1] - points[index][1]) / width;
    }
    tangents[0] = slopes[0];
    tangents[count - 1] = slopes[count - 2];
    for (let index = 1; index < count - 1; index += 1) {
      const previous = slopes[index - 1];
      const next = slopes[index];
      if (previous === 0 || next === 0 || previous * next <= 0) {
        tangents[index] = 0;
      } else {
        const previousWidth = widths[index - 1];
        const nextWidth = widths[index];
        const firstWeight = 2 * nextWidth + previousWidth;
        const secondWeight = nextWidth + 2 * previousWidth;
        tangents[index] =
          (firstWeight + secondWeight) /
          (firstWeight / previous + secondWeight / next);
      }
    }

    return function sampleCurve(input) {
      const x = clamp(input, 0, 1);
      let index = 0;
      while (index < count - 2 && x > points[index + 1][0]) index += 1;
      const start = points[index];
      const end = points[index + 1];
      const width = widths[index];
      const t = clamp((x - start[0]) / width, 0, 1);
      const t2 = t * t;
      const t3 = t2 * t;
      const value =
        (2 * t3 - 3 * t2 + 1) * start[1] +
        (t3 - 2 * t2 + t) * width * tangents[index] +
        (-2 * t3 + 3 * t2) * end[1] +
        (t3 - t2) * width * tangents[index + 1];
      return clamp(value, 0, 1);
    };
  }

  function buildLut(value) {
    const state = parseState(value);
    const composite = createSampler(state.composite);
    const red = createSampler(state.red);
    const green = createSampler(state.green);
    const blue = createSampler(state.blue);
    const data = new Uint8Array(LUT_SIZE * 4);
    for (let index = 0; index < LUT_SIZE; index += 1) {
      const common = composite(index / (LUT_SIZE - 1));
      const offset = index * 4;
      data[offset] = Math.round(red(common) * 255);
      data[offset + 1] = Math.round(green(common) * 255);
      data[offset + 2] = Math.round(blue(common) * 255);
      data[offset + 3] = 255;
    }
    return data;
  }

  function installStyle(getAsset) {
    if (!global.document || global.document.getElementById(STYLE_ID)) return;
    const bundled = typeof getAsset === "function" ? getAsset("text", STYLE_URL) : null;
    if (typeof bundled === "string") {
      const style = global.document.createElement("style");
      style.id = STYLE_ID;
      style.textContent = bundled;
      global.document.head.appendChild(style);
      return;
    }
    const link = global.document.createElement("link");
    link.id = STYLE_ID;
    link.rel = "stylesheet";
    link.href = STYLE_URL;
    global.document.head.appendChild(link);
  }

  function svgElement(document, name, className) {
    const element = document.createElementNS("http://www.w3.org/2000/svg", name);
    if (className) element.setAttribute("class", className);
    return element;
  }

  function curvePath(points) {
    const sample = createSampler(points);
    const segments = 96;
    let result = "";
    for (let index = 0; index <= segments; index += 1) {
      const x = index / segments;
      const command = index === 0 ? "M" : "L";
      result += `${command}${(x * 256).toFixed(2)} ${((1 - sample(x)) * 256).toFixed(2)} `;
    }
    return result.trim();
  }

  function createCurveControl(property, context) {
    const document = context.document;
    const controls = context.controls;
    const root = document.createElement("div");
    root.className = "editbox zoidium-color-curves-control";
    const editor = document.createElement("div");
    editor.className = "zoidium-color-curves-editor";
    root.appendChild(editor);

    const toolbar = document.createElement("div");
    toolbar.className = "zoidium-color-curves-toolbar";
    toolbar.setAttribute("role", "toolbar");
    toolbar.setAttribute("aria-label", "Curve channel");
    editor.appendChild(toolbar);

    const channelButtons = new Map();
    for (const channel of CHANNELS) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "zoidium-color-curves-channel";
      button.dataset.channel = channel.id;
      button.textContent = channel.shortName;
      button.title = `${channel.name} curve`;
      button.setAttribute("aria-label", button.title);
      toolbar.appendChild(button);
      channelButtons.set(channel.id, button);
    }

    const reset = document.createElement("button");
    reset.type = "button";
    reset.className = "zoidium-color-curves-reset";
    reset.title = "Reset current curve";
    reset.setAttribute("aria-label", reset.title);
    if (context.PZ?.ui?.generateIcon) reset.appendChild(context.PZ.ui.generateIcon("reset"));
    const resetLabel = document.createElement("span");
    resetLabel.textContent = "Reset";
    reset.appendChild(resetLabel);
    toolbar.appendChild(reset);

    const graph = document.createElement("div");
    graph.className = "zoidium-color-curves-graph";
    graph.tabIndex = 0;
    graph.setAttribute("role", "application");
    graph.setAttribute(
      "aria-label",
      "Color curve graph. Click to add a point, drag to adjust it, and press Delete to remove it."
    );
    editor.appendChild(graph);

    const svg = svgElement(document, "svg", "zoidium-color-curves-svg");
    svg.setAttribute("viewBox", "0 0 256 256");
    svg.setAttribute("preserveAspectRatio", "none");
    graph.appendChild(svg);
    const grid = svgElement(document, "path", "zoidium-color-curves-grid");
    grid.setAttribute("d", GRID_PATH);
    svg.appendChild(grid);
    const gridCenter = svgElement(document, "path", "zoidium-color-curves-grid zoidium-color-curves-grid-center");
    gridCenter.setAttribute("d", GRID_CENTER_PATH);
    svg.appendChild(gridCenter);
    const diagonal = svgElement(document, "path", "zoidium-color-curves-diagonal");
    diagonal.setAttribute("d", "M0 256 L256 0");
    svg.appendChild(diagonal);
    const referencePath = svgElement(document, "path", "zoidium-color-curves-reference");
    svg.appendChild(referencePath);
    const activePath = svgElement(document, "path", "zoidium-color-curves-active");
    svg.appendChild(activePath);
    const pointsLayer = svgElement(document, "g", "zoidium-color-curves-points");
    svg.appendChild(pointsLayer);

    const footer = document.createElement("div");
    footer.className = "zoidium-color-curves-footer";
    const status = document.createElement("span");
    status.className = "zoidium-color-curves-status";
    status.setAttribute("aria-live", "polite");
    footer.appendChild(status);
    const hint = document.createElement("span");
    hint.className = "zoidium-color-curves-hint";
    hint.textContent = "Click to add";
    footer.appendChild(hint);
    editor.appendChild(footer);

    let state = parseState(property.get());
    let activeChannel = "composite";
    let selectedIndex = null;
    let drag = null;
    let editing = false;

    function activePoints() {
      return state[activeChannel];
    }

    function updateStatus() {
      const points = activePoints();
      const point = selectedIndex == null ? null : points[selectedIndex];
      if (!point) {
        status.textContent = `${CHANNELS.find((channel) => channel.id === activeChannel).name} curve`;
        return;
      }
      status.textContent = `Input ${Math.round(point[0] * 255)}  Output ${Math.round(point[1] * 255)}`;
    }

    function draw() {
      editor.dataset.channel = activeChannel;
      for (const channel of CHANNELS) {
        const button = channelButtons.get(channel.id);
        const selected = channel.id === activeChannel;
        button.classList.toggle("is-active", selected);
        button.setAttribute("aria-pressed", String(selected));
      }
      if (activeChannel === "composite") {
        referencePath.removeAttribute("d");
      } else {
        referencePath.setAttribute("d", curvePath(state.composite));
      }
      activePath.setAttribute("d", curvePath(activePoints()));
      pointsLayer.replaceChildren();
      activePoints().forEach((point, index) => {
        const group = svgElement(document, "g", "zoidium-color-curves-point-wrap");
        group.dataset.pointIndex = String(index);
        if (index === selectedIndex) group.classList.add("is-selected");
        group.setAttribute("transform", `translate(${point[0] * 256} ${(1 - point[1]) * 256})`);
        const hit = svgElement(document, "circle", "zoidium-color-curves-point-hit");
        hit.setAttribute("r", "11");
        group.appendChild(hit);
        const visible = svgElement(document, "circle", "zoidium-color-curves-point");
        visible.setAttribute("r", "4.5");
        group.appendChild(visible);
        pointsLayer.appendChild(group);
      });
      updateStatus();
    }

    function beginEdit() {
      editing = true;
      controls.editStart.call(editor, property);
    }

    function setPropertyValue() {
      property.set(serializeState(state));
      draw();
    }

