uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;

uniform float keyPrimary;
uniform float keyOther1;
uniform float keyOther2;
uniform float suppression;
uniform float spillRange;
uniform float lumaCorrection;
uniform float tolerance;
uniform float desaturate;
uniform float neutral;
uniform float keyHue;

float aspPick(vec3 c, float idx) {
  if (idx < 0.5) {
    return c.r;
  }
  if (idx < 1.5) {
    return c.g;
  }
  return c.b;
}

float aspLumaWeight(float idx) {
  if (idx < 0.5) {
    return 0.2126;
  }
  if (idx < 1.5) {
    return 0.7152;
  }
  return 0.0722;
}

float aspHue(vec3 c) {
  float mx = max(c.r, max(c.g, c.b));
  float mn = min(c.r, min(c.g, c.b));
  float d = mx - mn;
  if (d < 0.0000001) {
    return 0.0;
  }
  float h;
  if (mx == c.r) {
    h = (c.g - c.b) / d;
    if (c.g < c.b) {
      h += 6.0;
    }
    h /= 6.0;
  } else if (mx == c.g) {
    h = ((c.b - c.r) / d + 2.0) / 6.0;
  } else {
    h = ((c.r - c.g) / d + 4.0) / 6.0;
  }
  return h;
}

void main() {
  vec2 uv = vUv * uvScale;
  vec4 px = texture2D(tDiffuse, uv);
  if (px.a <= 0.0) {
    gl_FragColor = px;
    return;
  }
  vec3 s = px.rgb / px.a;
  float w = 1.0;
  if (tolerance < 1.0) {
    float h = aspHue(s);
    float d0 = abs(h - keyHue);
    float d = min(d0, 1.0 - d0);
    w = clamp(1.0 - d / max(tolerance * 0.5, 0.0001), 0.0, 1.0);
  }
  float cO1 = aspPick(s, keyOther1);
  float cO2 = aspPick(s, keyOther2);
  float mx = max(cO1, cO2);
  float avg = 0.5 * (cO1 + cO2);
  float lim = mx + (avg - mx) * spillRange;
  float spill = max(aspPick(s, keyPrimary) - lim, 0.0) * suppression * w;
  float back = spill * aspLumaWeight(keyPrimary) * lumaCorrection + spill * neutral / 3.0;
  vec3 outc = s + vec3(back);
  if (keyPrimary < 0.5) {
    outc.r -= spill;
  } else if (keyPrimary < 1.5) {
    outc.g -= spill;
  } else {
    outc.b -= spill;
  }
  if (desaturate > 0.0 && spill > 0.0) {
    float l = 0.2126 * outc.r + 0.7152 * outc.g + 0.0722 * outc.b;
    float k = min(desaturate * min(spill * 4.0, 1.0), 1.0);
    outc += (vec3(l) - outc) * k;
  }
  gl_FragColor = vec4(outc * px.a, px.a);
}

text./plugins/native-fx/shaders/fx_colorcurve:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform sampler2D curveLUT;
uniform vec2 uvScale;

varying vec2 vUv;

void main() {
  vec2 sourceUv = vUv * uvScale;
  vec4 tex = texture2D(tDiffuse, sourceUv);
  float alpha = clamp(tex.a, 0.0, 1.0);
  vec3 straight = alpha > 0.00001 ? tex.rgb / alpha : vec3(0.0);
  vec3 lookupUv = (clamp(straight, 0.0, 1.0) * 255.0 + 0.5) / 256.0;
  vec3 graded;
  graded.r = texture2D(curveLUT, vec2(lookupUv.r, 0.5)).r;
  graded.g = texture2D(curveLUT, vec2(lookupUv.g, 0.5)).g;
  graded.b = texture2D(curveLUT, vec2(lookupUv.b, 0.5)).b;
  gl_FragColor = vec4(graded * alpha, alpha);
}

text./plugins/native-fx/shaders/fx_colordiffk:
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;

uniform vec3 keyColor;
uniform float keyDiff1;
uniform float keyDiff2;
uniform float keyPrimary;
uniform float keyOther1;
uniform float keyOther2;
uniform float accurate;
uniform float view;
uniform vec4 partialA;
uniform vec4 partialB;
uniform float partialAGamma;
uniform float partialBGamma;
uniform vec3 matteLevels;

float cdkLinear(float v) {
  if (v <= 0.04045) {
    return v / 12.92;
  }
  return pow((v + 0.055) / 1.055, 2.4);
}

float cdkPick(vec3 c, float idx) {
  if (idx < 0.5) {
    return c.r;
  }
  if (idx < 1.5) {
    return c.g;
  }
  return c.b;
}

float cdkLevels(float v, float inBlack, float inWhite, float gamma, float outBlack, float outWhite) {
  float t = clamp((v - inBlack / 255.0) / max((inWhite - inBlack) / 255.0, 0.0001), 0.0, 1.0);
  t = pow(t, 1.0 / max(gamma, 0.01));
  return clamp(outBlack / 255.0 + t * (outWhite - outBlack) / 255.0, 0.0, 1.0);
}

void main() {
  vec2 uv = vUv * uvScale;
  vec4 px = texture2D(tDiffuse, uv);
  if (view > 0.5 && view < 1.5) {
    gl_FragColor = px;
    return;
  }
  float a0 = max(px.a, 0.0);
  vec3 c = vec3(0.0);
  if (px.a > 0.000001) {
    c = px.rgb / px.a;
  }
  if (accurate > 0.5) {
    c = vec3(
      cdkLinear(clamp(c.r, 0.0, 1.0)),
      cdkLinear(clamp(c.g, 0.0, 1.0)),
      cdkLinear(clamp(c.b, 0.0, 1.0))
    );
  }
  float ua = 1.0 - clamp((cdkPick(c, keyPrimary) - cdkPick(c, keyOther1)) / keyDiff1, 0.0, 1.0);
  float ub = 1.0 - clamp((cdkPick(c, keyPrimary) - cdkPick(c, keyOther2)) / keyDiff2, 0.0, 1.0);
  float ca = cdkLevels(ua, partialA.x, partialA.y, partialAGamma, partialA.z, partialA.w);
  float cb = cdkLevels(ub, partialB.x, partialB.y, partialBGamma, partialB.z, partialB.w);
  float um = max(ua, ub);
  float cm = cdkLevels(max(ca, cb), matteLevels.x, matteLevels.y, matteLevels.z, 0.0, 255.0);
  if (view > 1.5) {
    float g = cm;
    if (view > 2.5 && view < 3.5) {
      g = um;
    } else if (view > 3.5 && view < 4.5) {
      g = ca;
    } else if (view > 4.5) {
      g = cb;
    }
    float m = g * a0;
    gl_FragColor = vec4(m, m, m, 1.0);
    return;
  }
  gl_FragColor = px * cm;
}

text./plugins/native-fx/shaders/fx_keycleaner:
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform float chatter;
uniform float contrast;
uniform float strength;
uniform float estSigma;
uniform float estStep;

void main() {
  vec2 uv = vUv * uvScale;
  vec2 texel = vec2(
    uvScale.x / max(resolution.x, 1.0),
    uvScale.y / max(resolution.y, 1.0)
  );
  vec4 px = texture2D(tDiffuse, uv);
  float a0 = max(px.a, 0.0);
  vec3 c = vec3(0.0);
  if (px.a > 0.000001) {
    c = px.rgb / px.a;
  }
  float na = a0;
  if (chatter > 0.5) {
    float sum = 0.0;
    for (int j = -2; j <= 2; j++) {
      for (int i = -2; i <= 2; i++) {
        sum += texture2D(tDiffuse, uv + vec2(float(i), float(j)) * texel).a;
      }
    }
    na = clamp((sum / 25.0 - 0.5) * 1.5 + 0.5, 0.0, 1.0);
  }
  if (estSigma > 0.001 && strength > 0.001 && a0 > 0.0001 && a0 < 0.999) {
    float sig2 = 2.0 * estSigma * estSigma;
    vec3 csum = vec3(0.0);
    float asum = 0.0;
    for (int j = -2; j <= 2; j++) {
      for (int i = -2; i <= 2; i++) {
        vec2 off = vec2(float(i), float(j)) * estStep * texel;
        float d2 = float(i * i + j * j) * estStep * estStep;
        float w = exp(-d2 / sig2);
        vec4 q = texture2D(tDiffuse, uv + off);
        csum += q.rgb * w;
        asum += max(q.a, 0.0) * w;
      }
    }
    if (asum > 0.0001) {
      float t = strength * (1.0 - a0);
      c += (csum / asum - c) * t;
    }
  }
  na = clamp((na - 0.5) * contrast + 0.5, 0.0, 1.0);
  if (a0 <= 0.000001) {
    na = 0.0;
  }
  gl_FragColor = vec4(c * na, na);
}

text./plugins/native-fx/shaders/fx_linearcolo:
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;

uniform vec3 keyColor;
uniform float matchMode;
uniform float tolerance;
uniform float softness;
uniform float keep;
uniform float view;

vec3 lckHsl(vec3 c) {
  float mx = max(c.r, max(c.g, c.b));
  float mn = min(c.r, min(c.g, c.b));
  float l = (mx + mn) * 0.5;
  float d = mx - mn;
  if (d < 0.0000001) {
    return vec3(0.0, 0.0, l);
  }
  float s = l > 0.5 ? d / (2.0 - mx - mn) : d / (mx + mn);
  float h;
  if (mx == c.r) {
    h = (c.g - c.b) / d;
    if (c.g < c.b) {
      h += 6.0;
    }
    h /= 6.0;
  } else if (mx == c.g) {
    h = ((c.b - c.r) / d + 2.0) / 6.0;
  } else {
    h = ((c.r - c.g) / d + 4.0) / 6.0;
  }
  return vec3(h, s, l);
}

void main() {
  vec2 uv = vUv * uvScale;
  vec4 px = texture2D(tDiffuse, uv);
  if (view > 0.5 && view < 1.5) {
    gl_FragColor = px;
    return;
  }
  float a0 = max(px.a, 0.0);
  vec3 c = vec3(0.0);
  if (px.a > 0.000001) {
    c = px.rgb / px.a;
  }
  float d;
  if (matchMode > 0.5 && matchMode < 1.5) {
    vec3 hc = lckHsl(c);
    vec3 hk = lckHsl(keyColor);
    if (hc.y < 0.02) {
      d = 1.0;
    } else {
      float dd = abs(hc.x - hk.x);
      d = min(dd, 1.0 - dd) * 2.0;
    }
  } else if (matchMode > 1.5) {
    float sc = c.r + c.g + c.b;
    float sk = keyColor.r + keyColor.g + keyColor.b;
    vec2 pc = sc <= 0.000001 ? vec2(1.0 / 3.0) : vec2(c.r / sc, c.g / sc);
    vec2 pk = sk <= 0.000001 ? vec2(1.0 / 3.0) : vec2(keyColor.r / sk, keyColor.g / sk);
    d = length(pc - pk) / 1.41421356;
  } else {
    d = length(c - keyColor) / 1.73205081;
  }
  float v;
  if (softness > 0.000001) {
    v = clamp((d - tolerance) / softness, 0.0, 1.0);
  } else if (d > tolerance) {
    v = 1.0;
  } else {
    v = 0.0;
  }
  if (keep > 0.5) {
    v = 1.0 - v;
  }
  if (view > 1.5) {
    float m = v * a0;
    gl_FragColor = vec4(m, m, m, 1.0);
    return;
  }
  gl_FragColor = px * v;
}

text./plugins/native-fx/shaders/fx_radialblur:
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform float density;
uniform float decay;
uniform float weight;
uniform vec2 center;

#ifdef DITHER
uniform float dither;
#endif

const int SAMPLES = 24;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(41.0, 289.0))) * 45758.5453);
}

void main() {
  vec2 uv = vUv;
  vec2 centerOffset = 0.5 + center.xy * 0.45;
  vec2 tuv = uv - centerOffset;
  float angleStep = density * 0.2 / float(SAMPLES);

#ifdef DITHER
  float noise = hash(floor(uv * resolution));
  float angleOffset = angleStep * (noise * 2.0 - 1.0) * dither;
  float c0 = cos(angleOffset);
  float s0 = sin(angleOffset);
  tuv = mat2(c0, -s0, s0, c0) * tuv;
#endif

#ifdef CONSTANT_BRIGHTNESS
  vec4 color = vec4(0.0);
#else
  vec2 sampleUV = tuv + centerOffset;
  vec4 color = texture2D(tDiffuse, sampleUV * uvScale) * 0.25;
#endif

  float wt = weight;
  float sum = 0.0;
  float aspect = resolution.x / resolution.y;
  float c = cos(angleStep);
  float s = sin(angleStep);
  mat2 rotPos = mat2(c, -s, s, c);
  mat2 rotNeg = mat2(c, s, -s, c);
  vec2 tuvPos = tuv;
  vec2 tuvNeg = tuv;

  vec2 pos = tuv + centerOffset;
  color += texture2D(tDiffuse, pos * uvScale) * wt;
  sum += wt;
  wt *= decay;

  for (int i = 0; i < SAMPLES / 2; i++) {
    tuvPos.x *= aspect;
    tuvPos = rotPos * tuvPos;
    tuvPos.x /= aspect;
    pos = tuvPos + centerOffset;
    color += texture2D(tDiffuse, pos * uvScale) * wt;
    sum += wt;

    tuvNeg.x *= aspect;
    tuvNeg = rotNeg * tuvNeg;
    tuvNeg.x /= aspect;
    pos = tuvNeg + centerOffset;
    color += texture2D(tDiffuse, pos * uvScale) * wt;
    sum += wt;
    wt *= decay;
  }

#ifdef CONSTANT_BRIGHTNESS
  color /= sum;
  gl_FragColor = color;
#else
  color *= 1.0 - dot(tuv, tuv) * 0.75;
  gl_FragColor = smoothstep(0.0, 1.0, color);
#endif
}
